CREATE TABLE IF NOT EXISTS intraday_detection_runs (run_id UUID PRIMARY KEY, worker_status TEXT NOT NULL, evaluation_version TEXT NOT NULL, started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), finished_at TIMESTAMPTZ, error TEXT);
CREATE TABLE IF NOT EXISTS intraday_detection_ticks (id BIGSERIAL PRIMARY KEY, run_id UUID NOT NULL REFERENCES intraday_detection_runs(run_id), tick_id UUID NOT NULL UNIQUE, planned_count INTEGER NOT NULL DEFAULT 0, executed_count INTEGER NOT NULL DEFAULT 0, deferred_count INTEGER NOT NULL DEFAULT 0, throttled_count INTEGER NOT NULL DEFAULT 0, failed_count INTEGER NOT NULL DEFAULT 0, queue_depth INTEGER NOT NULL DEFAULT 0, observed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), duration_ms INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS intraday_detection_transitions (id BIGSERIAL PRIMARY KEY, tick_id UUID REFERENCES intraday_detection_ticks(tick_id), market TEXT NOT NULL, code TEXT NOT NULL, from_state TEXT, to_state TEXT NOT NULL, evaluation_version TEXT NOT NULL, observed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), dedupe_key TEXT);
CREATE INDEX IF NOT EXISTS intraday_detection_ticks_observed_idx ON intraday_detection_ticks(observed_at DESC);
CREATE INDEX IF NOT EXISTS intraday_detection_ticks_run_idx ON intraday_detection_ticks(run_id, observed_at DESC);
CREATE INDEX IF NOT EXISTS intraday_detection_transitions_lookup_idx ON intraday_detection_transitions(market, code, observed_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS intraday_detection_transitions_dedupe_idx ON intraday_detection_transitions(dedupe_key) WHERE dedupe_key IS NOT NULL;
